import { useCallback, useRef, useState, type ReactNode } from "react";

export function ResizableSplitView({
  left,
  right,
  initialRatio = 0.36,
  min = 0.15,
  max = 0.8,
}: {
  left: ReactNode;
  right: ReactNode;
  initialRatio?: number;
  min?: number;
  max?: number;
}) {
  const [ratio, setRatio] = useState(initialRatio);
  const containerRef = useRef<HTMLDivElement>(null);

  const clamp = useCallback(
    (value: number) => Math.min(max, Math.max(min, value)),
    [min, max],
  );

  const onPointerMove = useCallback(
    (event: PointerEvent) => {
      const box = containerRef.current?.getBoundingClientRect();
      if (!box || box.width === 0) return;
      setRatio(clamp((event.clientX - box.left) / box.width));
    },
    [clamp],
  );

  const startDrag = () => {
    document.body.style.userSelect = "none";
    const stop = () => {
      document.body.style.userSelect = "";
      window.removeEventListener("pointermove", onPointerMove);
      window.removeEventListener("pointerup", stop);
    };
    window.addEventListener("pointermove", onPointerMove);
    window.addEventListener("pointerup", stop);
  };

  return (
    <div className="rsv-root" ref={containerRef}>
      <div className="rsv-pane" style={{ flexBasis: ratio * 100 + "%" }}>
        {left}
      </div>

      <div
        className="rsv-handle"
        role="separator"
        aria-orientation="vertical"
        aria-valuenow={Math.round(ratio * 100)}
        aria-valuemin={min * 100}
        aria-valuemax={max * 100}
        tabIndex={0}
        onPointerDown={startDrag}
        onDoubleClick={() => setRatio(initialRatio)}
        onKeyDown={(e) => {
          if (e.key === "ArrowLeft") setRatio((r) => clamp(r - 0.02));
          if (e.key === "ArrowRight") setRatio((r) => clamp(r + 0.02));
          if (e.key === "Enter") setRatio(initialRatio);
        }}
      />

      <div className="rsv-pane" style={{ flexBasis: (1 - ratio) * 100 + "%" }}>
        {right}
      </div>
    </div>
  );
}

cssRules:
.rsv-root {
  display: flex;
  height: 100%;
  min-height: 320px;
  overflow: hidden;
}
.rsv-pane {
  min-width: 0;
  overflow: auto;
  padding: 16px;
}
.rsv-handle {
  flex: 0 0 6px;
  position: relative;
  cursor: col-resize;
  background: var(--line-subtle, #e5e7eb);
  transition: background 0.15s ease;
}
.rsv-handle::after {
  content: '';
  position: absolute;
  inset: 0 -6px;
}
.rsv-handle:hover,
.rsv-handle:focus-visible {
  background: var(--accent, #6366f1);
  outline: none;
}
.rsv-handle:focus-visible {
  box-shadow: 0 0 0 2px var(--accent-soft, rgba(99, 102, 241, 0.35));
}
